/**
 * Blur: applies a Gaussian blur filter to the object.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { BlurFilter, type Filter } from "pixi.js";
import { Component } from "../core";
import { clearFilter, setFilter } from "./filter-stack";

export interface BlurParams {
  /** Blur strength, in pixels. 0 = no blur. */
  strength: number;
  /** Render quality (passes). Higher is smoother but slower. */
  quality: number;
}

/** Applies a Gaussian blur to the object. Stacks with other filter components on the same object. */
export class Blur extends Component<BlurParams> {
  static readonly componentName = "Blur";
  static readonly defaults: BlurParams = { strength: 8, quality: 4 };

  private filter: Filter | null = null;

  apply(): void {
    const next = new BlurFilter({
      strength: Math.max(0, this.params.strength),
      quality: Math.max(1, Math.round(this.params.quality)),
    });
    setFilter(this.target, this.filter, next);
    this.filter = next;
  }

  detach(): void {
    clearFilter(this.target, this.filter);
    this.filter = null;
  }
}
